// Strip layout.
use crate::grid::{Grid, Span};

struct Strip {
  gap: u32,
  pad: u32,
}

fn new(s: &Strip) -> Span {
  let mut w: Span = fit(s.gap, "on", 42); // up
  let v: Grid = cut(s.pad, "off", 7); // down
  return v;
}

